namespace GoPing.Services;

internal sealed record UnicodeEmoji(string Char, string Name);

internal sealed record UnicodeEmojiCategory(string Name, IReadOnlyList<UnicodeEmoji> Items);

/// <summary>
/// Обычные Unicode-эмодзи с категориями. В отличие от локального набора SVG,
/// они отправляются текстом и отображаются у всех пользователей.
/// </summary>
internal static class UnicodeEmojiCatalog
{
    private static UnicodeEmoji[] Emit(string block)
    {
        // Формат: "😀 grinning face|🥰 smiling face with hearts|..."
        return block.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(part =>
            {
                int space = part.IndexOf(' ');
                return space > 0
                    ? new UnicodeEmoji(part[..space], part[(space + 1)..])
                    : new UnicodeEmoji(part, part);
            })
            .ToArray();
    }

